#!/usr/bin/with-contenv bashio
# Serve /homeassistant/ha-report-hub (HA's /config/ha-report-hub, generated by ha_hub.py) read-only on the ingress port.
ROOT=/homeassistant/ha-report-hub
if [ ! -f "$ROOT/index.html" ]; then
  mkdir -p /tmp/empty
  echo '<!doctype html><meta charset="utf-8"><p>No reports yet. ha_hub.py (claude-ha) writes them to /config/ha-report-hub/ every Wednesday at 05:00.</p>' > /tmp/empty/index.html
  ROOT=/tmp/empty
fi
bashio::log.info "ha-report-hub: serving ${ROOT} on :8099 (ingress only)"
exec httpd -f -vv -p 8099 -h "$ROOT" -c /httpd.conf
